def prices_match(listed_price, settled_price):
    """判断挂牌价与结算价是否一致。"""
    return listed_price == settled_price

verification_tests:
from target import prices_match


def test_numeric_and_string_prices_match():
    assert prices_match(100, "100") is True


def test_whitespace_is_ignored():
    assert prices_match(" 100 ", "100") is True


def test_unparsable_price_does_not_match():
    assert prices_match("n/a", 100) is False
